    lI = getChar(53),
    lz = getChar(54),
    ["I."] = getChar(55),
    Il = getChar(56),
    Iz = getChar(57),
  }

  local list = {}
  local text2 = ""

  for match in string.gmatch(p4, "[^%+%>%<%-%~]+") do
    local text3 = ""

    for m = 1, #match, 2 do
      text3 = text3 .. (v20[string.sub(match, m, m + 1)] or "")
    end

    list[#list + 1] = string.char(tonumber(text3))
  end

  for n = #list, 1, -1 do
    text2 = text2 .. list[n]
  end

  return text2
end

